const data = $input.first().json.output;

// Guard: if AI returned a schema instead of data, treat as empty
const isSchema = (obj) => obj && obj.type && obj.properties;
if (isSchema(data)) {
  return {
    json: {
      job_title: "Not specified",
      company: "Not specified",
      matched_skills: [],
      missing_skills: [],
      match_score: 0,
      error: "AI returned schema instead of data"
    }
  };
}

// Ensure arrays
const matched = Array.isArray(data.matched_skills) ? data.matched_skills : [];
const missing = Array.isArray(data.missing_skills) ? data.missing_skills : [];

const total = matched.length + missing.length;
let score = 0;
if (total > 0) {
  score = Math.round((matched.length / total) * 100);
  score = Math.round(score / 5) * 5;
}

return {
  json: {
    job_title: data.job_title || "Not specified",
    company: data.company || "Not specified",
    matched_skills: matched,
    missing_skills: missing,
    match_score: score,
    recommendation: score >= 65
      ? "Kandydat pasuje na to stanowisko. Umiejętności są zgodne z wymaganiami."
      : "Kandydat nie pasuje — brakuje kluczowych umiejętności wymaganych w ofercie."
  }
};
